<?php require '../includes/bootstrap.php';require '../includes/operations.php';$user=staff_required();$title='Tạo đơn tại quầy';$error='';
if(post()){check_csrf();try{db()->beginTransaction();$id=create_staff_booking();db()->commit();flash('Đã tạo đơn xác nhận. Chọn phòng thực tế khi làm thủ tục nhận phòng.');go('reception/booking.php?id='.$id);}catch(DomainException $ex){if(db()->inTransaction())db()->rollBack();$error=$ex->getMessage();}}
$types=query('SELECT * FROM room_types WHERE active=1 ORDER BY id')->fetchAll();$selected=input('room_type_id',(string)($types[0]['id']??0));$key=booking_request_key();require '../includes/staff_header.php'; ?>
<div class="notice">Dùng cho khách gọi điện hoặc đến trực tiếp. Đơn được xác nhận ngay, giá lấy từ bảng giá hiện hành. Không tự gửi email.</div><form method="post" class="panel" id="desk-booking"><?=csrf()?><input type="hidden" name="request_key" value="<?=e($key)?>"><input type="hidden" name="quoted_price" value="<?php foreach($types as $r)if((string)$r['id']===$selected)echo $r['price']; ?>"><label>Loại phòng<select name="room_type_id" required><?php foreach($types as $r): ?><option value="<?=$r['id']?>" data-price="<?=$r['price']?>" <?=((string)$r['id']===$selected)?'selected':''?>><?=e($r['name'])?> — <?=money($r['price'])?> / đêm</option><?php endforeach; ?></select></label><div class="form-grid"><label>Ngày nhận<input type="date" name="check_in" min="<?=date('Y-m-d')?>" value="<?=e(input('check_in',date('Y-m-d')))?>" required></label><label>Ngày trả<input type="date" name="check_out" value="<?=e(input('check_out',date('Y-m-d',strtotime('+1 day'))))?>" required></label><label>Số phòng<input type="number" name="quantity" value="<?=e(input('quantity','1'))?>" min="1" max="5" required></label><label>Tổng số khách<input type="number" name="guests" value="<?=e(input('guests','2'))?>" min="1" max="20" required></label></div><p id="desk-total" aria-live="polite">Chọn ngày và loại phòng để xem tổng tiền.</p><label>Họ tên<input name="guest_name" value="<?=e(input('guest_name'))?>" minlength="2" maxlength="100" required></label><div class="form-grid"><label>Email của khách<input type="email" name="email" value="<?=e(input('email'))?>" required maxlength="190"></label><label>Điện thoại<input name="phone" value="<?=e(input('phone'))?>" type="tel" maxlength="25" required></label></div><label>Ghi chú<textarea name="note" maxlength="1000"><?=e(input('note'))?></textarea></label><button class="button">TẠO ĐƠN & XÁC NHẬN</button></form><?php require '../includes/staff_footer.php'; ?>
